--- Wrap a registry glyph in a self-contained, currentColor-tinted <svg>.
-- The 1em sizing makes inline `{{< icon >}}` track the font; inside a stat's
-- `.viz` the `.viz svg{width:100%;height:100%}` rule (B4) overrides it.
-- @param name string  a key in ICONS
-- @return string|nil  the full <svg> markup, or nil if the name is unknown
local function icon_svg(name)
  local inner = ICONS[name]
  if inner == nil then
    return nil
  end
  return table.concat({
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16"',
    ' class="deck-icon bi bi-',
    name,
    '" width="1em" height="1em" fill="currentColor"',
    ' style="vertical-align:-0.125em" aria-hidden="true">',
    inner,
    "</svg>",
  })
end

return {
  icons = ICONS,
  icon_svg = icon_svg,
}
